mapper.select:
select

from yh_user_permission up where up.`status`=1 and up.permission_id in (
	select permission_id from yh_user_role_permission urp where urp.role_id in (
		select uur.roleId role_id from yh_user_role_power uur where uur.userId=#{upmsUserId,jdbcType=VARCHAR}
	)
	union
	select user_role from yh_user_role_relation uup1 where uup1.user_code=#{upmsUserId,jdbcType=VARCHAR} and uup1.type=1
)
and up.permission_id not in (
	select user_role from yh_user_role_relation uup2 where uup2.user_code=#{upmsUserId,jdbcType=VARCHAR} and uup2.type=-1
) order by up.orders asc

select

from yh_user_role ur where ur.role_id in (
	select uur.roleId from yh_user_role_power uur where uur.userId=#{upmsUserId,jdbcType=VARCHAR}
)
